namespace App\Models;

use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;
use App\Models\Concerns\HasAudits;


/**
 * Generated Eloquent model for the pendaftaran_kursus table.
 */
class CourseRegistration extends Model 
{
	use HasFactory;
    use HasAudits;
    use SoftDeletes;
    
    
    /**
     *
     * @var string
     */
    protected $table = 'pendaftaran_kursus';
    /**
     *
     * @var string
     */
    protected $primaryKey = 'id';
    /**
     *
     * @var array<int, string>
     */
    protected $fillable = [
        
        'pelajar_id',
        'kursus_id',
        'tarikh_pendaftaran',
        'gred',
        'dokumen_lengkap'
    
    ];
    
    


    public function registrationApproval()
    {
        return $this->hasOne(RegistrationApproval::class, 'pendaftaran_id', 'id');
    }
    public function student()
    {
        return $this->belongsTo(Student::class, 'pelajar_id', 'id');
    }
    public function course()
    {
        return $this->belongsTo(Course::class, 'kursus_id', 'id');
    }	




}
